// ── COMPILER ───────────────────────────────────────────────────────────

function clean(parts) { return parts.filter(Boolean).join(" ").replace(/\s+/g, " ").trim(); }

function roleList(b) { return b.roles === "No characters" ? [] : b.roles.split(",").map(x => x.trim()).filter(Boolean); }

function mustRole(name, b) { if (!ROLE[name]) throw new Error(`Unknown ROLE "${name}" in ${b.ref}`); return ROLE[name]; }

function castLock(b) {
  const names = roleList(b);
  if (!names.length) return "CHARACTER COUNT: exactly 0. No person, head, face, hand or silhouette anywhere in this frame.";
  const upper = names.map(n => n.toUpperCase()).join(", ");
  if (b.shotSize === "HANDS") return `CHARACTER COUNT: exactly ${names.length} (${upper}), seen only as hands and forearms entering the frame; no head or face anywhere in the frame.`;
  return `CHARACTER COUNT: exactly ${names.length}: ${upper}. No other person, head or silhouette anywhere in the frame.`;
}

function heightBlock(b) {
  if (b.shotSize === "HANDS") return "";
  const names = roleList(b);
  const by = age => names.filter(n => mustRole(n, b).age === age).map(n => n.toUpperCase());
  const adults = by("adult"), teens = by("teen"), kids = by("child");
  const out = [];
  if (adults.length && teens.length) { const her = adults.length === 1 ? (/^(MOM|SARAH)$/.test(adults[0]) ? "hers" : "his") : "the adults'"; out.push(`HEIGHTS: ${teens.join(" and ")} stand${teens.length > 1 ? "" : "s"} clearly shorter than ${adults.join(" and ")}, as in the MOM-and-SON height sheet — standing together, the teenager's chin is at about the adult's shoulder and his face sits clearly lower than ${her}; seated or cropped, the teenager still reads as the younger, leaner one.`); }
  if (kids.length) out.push(`${kids.join(" and ")} ${kids.length > 1 ? "are young children whose heads reach" : "is a young child whose head reaches"} only about halfway up an adult's standing height, with ${kids.every(k => (ROLE[k.charAt(0) + k.slice(1).toLowerCase()] || ROLE[Object.keys(ROLE).find(r => r.toUpperCase() === k)] || {}).from === "Son") ? "the head a little bigger for the body than SON's — about one-third of the height — with a young child's short body" : "the head about one-fifth of their height"}, short arms and legs — never an oversized bobble head.`);
  return out.join(" ");
}

// Revision 5: the reference block names only who is in the frame — MOM and SON as their references, everyone else as a copy of
// one of them with a short list of changes — and tells the model when MOM or SON are absent, so they aren't drawn in.
function refLock(b) {
  const names = roleList(b);
  if (b.shotSize === "HANDS") return `HANDS FROM THE ATTACHED REFERENCE IMAGES: ${names.map(n => n.toUpperCase()).join(" and ")} appear${names.length > 1 ? "" : "s"} only as mitten hands on short forearm lines, drawn exactly as in the attached MOM and SON references — the same small white mitten with one thumb bump and no cuff, the same thin black ink forearm line and line thickness.`;
  const who = names.map(n => { const R = mustRole(n, b), N = n.toUpperCase();
    return R.ref ? `${N} is exactly the attached ${N} reference images — ${n === "Mom" ? "with her adult proportions" : "with his teenage proportions"}` : `${N} has no reference image, so ${N} is drawn by copying the attached ${R.from.toUpperCase()} reference exactly and changing only ${R.short} (described below)`; });
  const absent = ["Mom", "Son"].filter(r => !names.includes(r)).map(r => r.toUpperCase());
  const absentLine = absent.length ? ` ${absent.join(" and ")} ${absent.length > 1 ? "do" : "does"} not appear in this frame — use ${absent.length > 1 ? "their images" : "that image"} only as the drawing style.` : "";
  return `CHARACTERS FROM THE ATTACHED REFERENCE IMAGES (the MOM and SON images are the master for every character): ${who.join("; ")} — everyone with ${REF_SPEC}.${absentLine} No eyelashes, no clothing beyond the small items named, no filled body. Only the pose, expression, camera and setting change here; nobody is redesigned.`;
}
function roleText(b) { return roleList(b).map(n => mustRole(n, b).text).join(" "); }

function paint(text, mood, b) {
  const P = framePalette({ ...b, mood });
  const map = { WALL: P.wall, FLOOR: P.floor, FURN: P.furn, SKY: P.sky, GROUND: P.ground, FIELD: P.field };
  return text.replace(/\{(WALL|FLOOR|FURN|SKY|GROUND|FIELD)\}/g, (_, k) => /^white with (.+)$/.test(map[k][0]) ? `white (${map[k][1]}) with ${map[k][0].slice(11)}` : `${map[k][0]} (${map[k][1]})`)
    .replace(/(\bsky \(#[0-9A-Fa-f]{6}\)) sky\b/g, "$1"); // Version 7
}

function worldBlock(b) { const t = worldBlock0(b), w = wallObjects(b); return w ? t.replace(/the walls are plain and empty/g, `the walls are plain apart from ${w}`).replace(/the wall is plain and empty/g, `the wall is plain apart from ${w}`) : t; }
