  if (b.mood === "WHITE" && roleList(b).length && ["CLOSE", "XCLOSE"].includes(b.shotSize)) return "SETTING: only a plain, clean, pure white (#FFFFFF) background — no room, no furniture, no wall or floor lines; nothing but the characters" + ((b.props || []).length ? " and the story objects named here" : "") + ". The face and its expression carry the whole frame."; // Thomas (Oct 2026): sometimes a face alone on white, no colour, no background
  if (b.shotSize === "XCLOSE") { // Revision 3: a full room description pulls an extreme close-up back into a medium shot
    const k = (W.text.match(/\{(WALL|FIELD|SKY|FLOOR|FURN|GROUND)\}/) || [, "WALL"])[1];
    const noun = { WALL: "wall", FIELD: "background", SKY: "sky", FLOOR: "floor", FURN: "surface", GROUND: "ground" }[k];
    return "SETTING: only " + paint(`a flat {${k}}`, b.mood, b) + ` ${noun} behind the head, seen straight on at eye level — no floor, and no arms, legs or feet in the frame; the rest of the place is out of frame, because the camera is extremely close.`;
  }
